"""Maximal Rectangle — histogram per row.

Each row becomes a histogram of consecutive 1s above it; the answer is the best
largest-rectangle-in-histogram across all rows.

Time: O(m*n)   Space: O(n)
"""
from typing import List


class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0
        n = len(matrix[0])
        heights = [0] * n
        best = 0
        for row in matrix:
            for j, cell in enumerate(row):
                heights[j] = heights[j] + 1 if cell == "1" else 0
            best = max(best, self._largest(heights))
        return best

    @staticmethod
    def _largest(heights: List[int]) -> int:
        stack, best = [], 0
        for i, height in enumerate(heights + [0]):
            while stack and heights[stack[-1]] >= height:
                h = heights[stack.pop()]
                width = i - stack[-1] - 1 if stack else i
                best = max(best, h * width)
            stack.append(i)
        return best
